import path from 'node:path';
export async function assertDetailActionFeedback({page,frame,check,out}){
 const color=async(button,property,values)=>button.evaluate((el,{property,values})=>new Promise((resolve,reject)=>{const end=performance.now()+2000;const sample=()=>{const value=getComputedStyle(el)[property];if(values.includes(value))resolve(value);else if(performance.now()>end)reject(Error(property+'='+value));else requestAnimationFrame(sample);};sample();}),{property,values});
 const tools=frame.locator('.inventory-product-tools'),button=label=>tools.getByRole('button',{name:label,exact:true});
 check(await tools.locator('button[data-tooltip]').count()===await tools.locator('button').count(),'详情每个操作均有完整用途说明');
 await button('修改售价').hover();await frame.locator('.app-hover-tip').filter({hasText:'填写目标售价'}).waitFor();check((await frame.locator('.app-hover-tip').textContent()).includes('提交网站并回读'),'悬停说明解释修改范围及网站回读');await page.screenshot({path:path.join(out,'actions-tooltip-1280.png')});
 await button('产品上架').hover();await frame.locator('.app-hover-tip').filter({hasText:'网站已上架，无需重复上架'}).waitFor();check(await button('产品上架').isDisabled(),'禁用按钮仍说明当前不可操作原因');
 await button('修改介绍').focus();check(await frame.locator('.app-hover-tip').isVisible(),'键盘焦点也可查看说明');await button('修改介绍').hover();await page.mouse.down();check(Boolean(await color(button('修改介绍'),'backgroundColor',['rgb(92, 32, 184)'])),'鼠标按下时显示更深的按压反馈');await page.screenshot({path:path.join(out,'actions-pressed-1280.png')});await page.mouse.up();const editor=frame.getByRole('dialog').last();await editor.getByLabel('修改介绍',{exact:true}).waitFor();check(await button('修改介绍').getAttribute('data-action-state')==='active','打开编辑弹窗后原按钮保持当前操作状态');check(Boolean(await color(button('修改介绍'),'backgroundColor',['rgb(124, 58, 237)','rgb(105, 38, 216)'])),'点击后紫色实底与未选按钮可区分');await page.screenshot({path:path.join(out,'actions-open-dialog-1280.png')});await editor.getByRole('button',{name:'取消',exact:true}).click();check(await button('修改介绍').getAttribute('data-action-state')==='active','取消编辑保持点击反馈，不冒充保存成功');
 let release,entered,requests=0,fail=false;const gate=new Promise(r=>release=r),started=new Promise(r=>entered=r);const intercept=async route=>{let p;try{p=route.request().postDataJSON();}catch{}if(p?.action!=='website-read')return route.fallback();requests++;if(fail)return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({ok:false,error:{message:'虚构读取失败'}})});entered();await gate;return route.continue();};
 await page.route('**/api/**',intercept);
 try{
  const width=(await button('读取商品记录').boundingBox()).width;await Promise.all([button('读取商品记录').click(),started]);check(await button('读取商品记录').textContent()==='读取中…','读取处理中显示明确文字反馈');check(await button('读取商品记录').getAttribute('aria-busy')==='true'&&await button('读取商品记录').isDisabled(),'读取期间标记忙碌并禁止重复提交');await button('读取商品记录').evaluate(b=>{b.click();b.click();});check(requests===1,'连续重复点击只产生一次读取请求');check(Math.abs((await button('读取商品记录').boundingBox()).width-width)<1,'忙碌文案不引起按钮宽度跳变');await page.setViewportSize({width:820,height:640});await page.screenshot({path:path.join(out,'actions-reading-820.png')});release();await tools.locator('button[data-action-label="读取商品记录"][data-action-state=done]').waitFor();await button('读取商品记录').hover();check(Boolean(await color(button('读取商品记录'),'borderTopColor',['rgb(22, 136, 101)'])),'读取实际成功后显示绿色完成状态，悬停仍保持');check(!await button('修改介绍').isDisabled(),'读取结束后恢复其它操作');await page.screenshot({path:path.join(out,'actions-complete-820.png')});
  fail=true;await button('读取商品记录').click();await tools.locator('button[data-action-label="读取商品记录"][data-action-state=error]').waitFor();check(Boolean(await color(button('读取商品记录'),'borderTopColor',['rgb(209, 75, 75)'])),'读取失败显示错误状态，不伪装完成');check(!await button('读取商品记录').isDisabled(),'失败后允许再次操作');await page.screenshot({path:path.join(out,'actions-failed-820.png')});
 }finally{release();await page.unroute('**/api/**',intercept);await page.setViewportSize({width:1280,height:820});}
}
